#include <iostream>
#include <string>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales, double rate)
        : firstName(first), lastName(last), socialSecurityNumber(ssn),
          grossSales(sales), commissionRate(rate) {}

    // Getters allowing controlled access to private data
    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(const std::string& first, const std::string& last,
                               const std::string& ssn, double sales, double rate, double salary)
        : CommissionEmployee(first, last, ssn, sales, rate), baseSalary(salary) {}

    double earnings() const {
        // Must use inherited getters because base members are private
        return baseSalary + (getCommissionRate() * getGrossSales());
    }

    void print() const {
        std::cout << "Employee: " << getFirstName() << " " << getLastName()
                  << "\nBase salary: " << baseSalary
                  << "\nEarnings: " << earnings() << "\n";
    }

private:
    double baseSalary;
};

int main() {
    BasePlusCommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);
    std::cout << std::fixed << std::setprecision(2);
    emp.print();
    return 0;
}

#include <iostream>
#include <string>

// Base class utilizing protected data members
class CommissionEmployeeProtected {
public:
    CommissionEmployeeProtected(const std::string& first, const std::string& last, double sales, double rate)
        : firstName(first), lastName(last), grossSales(sales), commissionRate(rate) {}

protected:
    std::string firstName;
    std::string lastName;
    double grossSales;
    double commissionRate;
};

// Derived class can directly access protected members of base
class BasePlusCommissionEmployeeProtected : public CommissionEmployeeProtected {
public:
    BasePlusCommissionEmployeeProtected(const std::string& first, const std::string& last,
                                        double sales, double rate, double salary)
        : CommissionEmployeeProtected(first, last, sales, rate), baseSalary(salary) {}

    double earnings() const {
        // Direct access permitted due to protected specifier
        return baseSalary + (commissionRate * grossSales);
    }

    void print() const {
        std::cout << "Employee: " << firstName << " " << lastName
                  << "\nGross sales: " << grossSales
                  << "\nCommission rate: " << commissionRate
                  << "\nTotal earnings: " << earnings() << "\n";
    }

private:
    double baseSalary;
};

int main() {
    BasePlusCommissionEmployeeProtected emp("Bob", "Lewis", 5000.0, 0.04, 300.0);
    emp.print();
    return 0;
}
